const input = $('Called by a workflow').first().json;
const row = input.row;
const q = input.config.alert_queue;
let payload = null;
let parseError = null;
try { payload = JSON.parse(row.payload); } catch (e) { parseError = e.message; }
const earlier = $('Same alert running').all().map((i) => i.json)
  .filter((r) => r.id !== undefined && r.id !== row.id && r.id < row.id);
let action = 'run';
let reason = null;
if (earlier.length > 0) {
  action = 'yield';
  reason = `row ${earlier[0].id} for the same Wazuh alert is running: given back to wait for it (no concurrent copies, A78)`;
} else if (parseError !== null) {
  action = 'fail';
  reason = `queued payload is not JSON (${parseError})`;
} else if (Number(row.attempts) > q.max_attempts) {
  action = 'fail';
  reason = `attempts exhausted (${q.max_attempts})`;
}
return [{ json: { action, reason, payload, row_id: row.id, alert_id: row.alert_id, attempt: Number(row.attempts) } }];

// The same input recv-wazuh-alert used to pass, plus a fresh lib-config.
const input = $('Called by a workflow').first().json;
const d = $input.first().json;
return [{ json: { ...d.payload, config: input.config,
  queue: { row_id: d.row_id, attempt: d.attempt, slot: input.slot.name } } }];

// How the row ends: done, back to pending (retry), or failed (parked).
const input = $('Called by a workflow').first().json;
const row = input.row;
const q = input.config.alert_queue;
const d = $('Decide').first().json;
const OK = ['created', 'duplicate', 'repaired', 'parked', 'skipped'];
let u;
let park = null;
let outcome = 'none';
if (d.action === 'run') {
  const r = $('Playbook (by route)').first().json;
  if (OK.includes(r.outcome)) {
    outcome = r.outcome;
    u = { status: 'done', attempts: d.attempt, note: `attempt ${d.attempt}: ${r.outcome}` + (r.thehive_alert_id ? `, TheHive ${r.thehive_alert_id}` : '') };
  } else {
    outcome = 'error';
    const e = r.error;
    const msg = `${typeof e === 'string' ? e : (e?.message ?? JSON.stringify(e ?? r))}`.slice(0, 500);
    if (d.attempt >= q.max_attempts) {
      u = { status: 'failed', attempts: d.attempt, note: `attempt ${d.attempt} of ${q.max_attempts} failed: ${msg}; parked` };
      park = msg;
    } else {
      u = { status: 'pending', attempts: d.attempt, note: `attempt ${d.attempt} failed: ${msg}; will retry` };
    }
  }
} else if (d.action === 'yield') {
  u = { status: 'pending', attempts: d.attempt - 1, note: d.reason };
} else {
  outcome = 'error';
  u = { status: 'failed', attempts: d.attempt, note: `${d.reason}; parked` };
  park = d.reason;
}
return [{ json: { ...u, outcome, finished_ms: ['done', 'failed'].includes(u.status) ? Date.now() : 0, park } }];

const input = $('Called by a workflow').first().json;
const u = $('Row update').first().json;
return [{ json: {
  error_class: 'queue_attempts_exhausted', stage: 'alert queue (lib-alert-queue-drain)', workflow: $workflow.name,
  execution_id: $execution.id, node: 'Playbook (by route)', wazuh_alert_id: input.row.alert_id,
  thehive_alert_id: null, http_status: null, error_code: null, attempts: u.attempts,
  message: `alert ${input.row.alert_id}: ${u.note}`, payload: { queue_row: input.row.id } } }];

const input = $('Called by a workflow').first().json;
const u = $('Row update').first().json;
const finished = $('Finish row (compare-and-set)').first().json.id !== undefined;
const dp = input.depth;
return [{ json: {
  status: `alert ${input.row.alert_id} (row ${input.row.id}, ${input.slot.name}): ${u.note}`
    + (finished ? '' : ' [row changed meanwhile: not updated]')
    + `; queue before this run: ${dp.pending} pending, ${dp.running} running`,
  row_id: input.row.id, wazuh_alert_id: input.row.alert_id, row_status: u.status, outcome: u.outcome,
  attempt: u.attempts, finished, depth: dp,
} }];
